# output computed orthogonal comps and mark
seen=set();out=[row[:] for row in a]; groups=[]
for r in range(R):
 for c in range(C):
  if a[r][c]==0 and (r,c) not in seen:
   st=[(r,c)];seen.add((r,c));co=[]
   while st:
    x,y=st.pop();co.append((x,y))
    for dx,dy in ((1,0),(-1,0),(0,1),(0,-1)):
     q=(x+dx,y+dy)
     if 0<=q[0]<R and 0<=q[1]<C and a[q[0]][q[1]]==0 and q not in seen:seen.add(q);st.append(q)
   if len(co)>1:
    groups.append(co)
    for x,y in co:out[x][y]=8
print([len(g) for g in groups]); print('\n'.join(' '.join(map(str,row)) for row in out))
